/* Living-world bridge: existing records remain the source of truth. */
const livingModel=window.PPModel;
const openDiaryEntries=new Set();
let livingSnapshot=structuredClone(state),livingFeedback=null,livingTimer=null,routeFrame=0,routeMarker=null,routePlaying=false,motionObserver=null,routeCleanup=null,lastQuestPoint=null;
function livingPreferences(){
  const trip=state.trips.find(t=>t.id===selectedTrip)||nextTrip()||state.trips[0],destination=state.destinations.find(d=>d.id===selectedDestination);
  const season=livingModel.resolveSeason(state.profile,trip,destination),motion=state.profile.ambientMotion!=='off';
  const skiNow=state.skiTrips.some(s=>s.start&&s.start<=today()&&(s.end?s.end>=today():s.start===today()));
  const outfit=state.profile.selectedOutfitId||'casual';
  const baseMessage={home:state.skiTrips.length?`${state.skiTrips.at(-1).resort} is on your mountain list. Packing and quest suggestions are ready to review.`:'A little planning today, a whole world of memories tomorrow.',trips:'Open a diary entry to add details or mark an adventure complete.',map:'Tap a pin to meet a place. Route previews follow your saved stop order.',packing:state.packing.length?`${state.packing.length-packed()} saved item${state.packing.length-packed()===1?'':'s'} still to pack. Each little thing has its place.`:'Start with your essentials, then accept only the suggestions you need.',tasks:'Small quests, big adventures. Every completed quest earns 25 XP.',budget:'Estimates help you plan. Only recorded actual expenses count as spending.',bookings:'Keep a ticket’s reference and confirmation together, ready for departure.',ski:'Link your mountain stop, then review equipment, lift passes and your budget.',journal:'Your real adventures unlock stamps. The little moments make the best souvenirs.',settings:'Make this little world yours. Your manual season stays the way you choose.'}[page]||'Let’s explore a little further.';
  return {season,motion,outfit,mode:livingFeedback?.mode||(page==='map'?'map':page==='budget'?'thinking':'idle'),dialogue:livingFeedback?.message||baseMessage};
}
window.PPLiving={toggleMotion(){state.profile.ambientMotion=state.profile.ambientMotion==='off'?'on':'off';save()},preferences:livingPreferences};
const livingSave=save;
save=function(){
  let event=livingModel.milestone(livingSnapshot,state);
  const base=state.profile.baseCurrency,total=s=>s.expenses.filter(e=>e.kind==='actual').reduce((sum,e)=>sum+(e.currency===base?Number(e.amount)||0:e.baseCurrency===base?Number(e.baseAmount)||0:0),0),budget=Number(state.profile.exchangeBudget);
  if(!event&&budget>0&&livingSnapshot.profile.exchangeBudget===state.profile.exchangeBudget&&livingSnapshot.profile.baseCurrency===base){const previous=total(livingSnapshot)/budget,current=total(state)/budget;if(previous<1&&current>=1||previous<.8&&current>=.8)event={mode:'thinking',title:current>=1?'Budget check-in':'80% of your budget recorded',message:current>=1?'Your recorded spending has reached your budget. Review the ledger before your next purchase.':'There is still room in your budget. Check upcoming commitments too.',kind:'budget'};}
  if(!event&&state.expenses.some(e=>!livingSnapshot.expenses.some(old=>old.id===e.id)))event={mode:'happy',title:'A coin in the ledger',message:'Your expense is saved in its recorded stage and currency.',kind:'expense'};
  livingFeedback=event?{...event,message:event.title+' — '+event.message}:livingFeedback;
  livingSave();livingSnapshot=structuredClone(state);
  if(event){window.PPReact.celebrate(event,livingPreferences().motion);if(event.recordId){const el=document.querySelector(`[data-pack-check="${event.recordId}"],[data-task-check="${event.recordId}"],[data-drag-activity="${event.recordId}"]`);el?.closest('.inventory-slot,.quest,.diary-activity')?.classList.add(event.kind.startsWith('packing')?'just-packed':'just-completed');}clearTimeout(livingTimer);livingTimer=setTimeout(()=>{window.PPReact.dismissAchievement();livingFeedback=null},6500);}
  if(event?.kind==='quest'&&lastQuestPoint&&livingPreferences().motion&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const target=document.querySelector('.avatar-chip')?.getBoundingClientRect();if(target){const orb=document.createElement('span');orb.className='xp-orb';orb.textContent='+25 XP';orb.style.left=lastQuestPoint.x+'px';orb.style.top=lastQuestPoint.y+'px';document.body.append(orb);const animation=orb.animate([{transform:'translate(0,0)',opacity:1},{transform:`translate(${target.left-lastQuestPoint.x}px,${target.top-lastQuestPoint.y}px) scale(.5)`,opacity:0}],{duration:850,easing:'ease-in',fill:'forwards'});animation.onfinish=()=>orb.remove();}}
};
const originalActivityRow=activityRow;
activityRow=function(a){const complete=a.status==='completed',icon=a.type==='transport'?(/flight|plane|fly/i.test(a.title)?'plane':'train'):a.type==='skiing'?'ski':a.type==='food'?'food':a.type==='accommodation'?'home':'camera';return `<details class="diary-activity ${complete?'activity-done':''}" draggable="true" data-drag-activity="${a.id}" ${openDiaryEntries.has(a.id)?'open':''}><summary>${pixelIcon(icon)}<span><strong>${esc(a.title)}</strong><small>${esc(a.time||'Time flexible')} · ${esc(a.type)} · ${esc(a.status)}</small></span></summary><div class="activity-details">${a.notes?`<p>${esc(a.notes)}</p>`:'<p class="muted">Add the little details that make this stop yours.</p>'}${a.address?`<p>${esc(a.address)}</p>`:''}${a.cost?`<p>Estimated ${money(a.cost,a.currency||'SGD')}</p>`:''}${a.type==='transport'?`<p class="activity-route">${esc(destName(a.destinationId))} · Saved trip stop order is available on the map.</p>`:''}<div class="activity-controls"><button type="button" class="btn small primary" data-action="completeActivity" data-id="${a.id}">${complete?'Reopen activity':'Mark completed'}</button><button class="btn small" data-action="editActivity" data-id="${a.id}">Edit</button>${a.type==='transport'?`<button class="btn small" data-action="previewActivityRoute" data-id="${a.id}">View route</button>`:''}<button class="btn small" data-action="deleteActivity" data-id="${a.id}">Delete</button></div></div></details>`};
actions.completeActivity=({id})=>{const a=state.activities.find(a=>a.id===id);if(!a)return;if(a.status==='completed'){a.status=a.previousStatus||'planned';delete a.previousStatus}else{a.previousStatus=a.status;a.status='completed'}save()};
actions.previewActivityRoute=({id})=>{const a=state.activities.find(a=>a.id===id),d=state.destinations.find(d=>d.id===a?.destinationId);filters.mapTrip=d?.tripId||'';filters.routeTrip=d?.tripId||'';go('map')};
const originalPackingSuggestions=packingSuggestions;
packingSuggestions=function(){const out=originalPackingSuggestions(),season=livingPreferences().season,extras=season==='summer'?[['Sunscreen','Summer travel','personal bag','',.1],['Sun hat','Sunny days','cabin luggage','',.1]]:season==='autumn'||season==='spring'?[['Light rain jacket','Changeable spring and autumn weather','cabin luggage','',.4]]:[];for(const [name,reason,category,icon,weight] of extras)if(!state.packing.some(p=>p.name.toLowerCase()===name.toLowerCase())&&!state.dismissed.includes(name.toLowerCase())&&!out.some(p=>p.name===name))out.push({name,reason,category,icon,weight});return out};
actions.packBagTab=({value})=>{filters.packBag=value||'';render()};
actions.filterExpenseMonth=({value})=>{filters.expenseMonth=filters.expenseMonth===value?'':value;render();document.querySelector('.monthly-ledger')?.scrollIntoView({block:'start',behavior:'auto'})};
