actions.openSkiDestination=({id})=>{const s=state.skiTrips.find(s=>s.id===id);if(s?.destinationId)window.openMapDestination(s.destinationId)};
function journalEnhancements(){const visited=state.destinations.filter(d=>d.status==='visited').sort((a,b)=>(a.arrival||'9999').localeCompare(b.arrival||'9999'));if(!visited.length)return;const panel=document.createElement('section');panel.innerHTML=`<h3>Footprints from the road</h3><div class="visited-timeline">${visited.map(d=>`<div>${postcard(d.name)}<div><strong>${esc(d.name)}</strong><small>${esc(d.country)} · ${date(d.arrival)}</small><button type="button" class="btn small" data-action="openVisitedStop" data-id="${d.id}">Open diary →</button></div></div>`).join('')}</div>`;document.querySelector('.stamp-grid')?.after(panel);bindActions(panel)}
