function settingsEnhancements(visual){const list=document.querySelector('.settings-list');if(!list)return;const panel=document.createElement('section');panel.className='card visual-preferences';panel.innerHTML=`<h3>${pixelIcon('flower')} Your living world</h3><p>Automatic follows the selected destination’s arrival, then the selected trip’s departure month. Undated plans use winter. Manual seasons stay selected across pages and reloads.</p><div class="form-grid">${selectField('visualTheme','Scene theme',[{id:'auto',name:'Automatic · selected trip'},...livingModel.seasons.map(s=>({id:s,name:s[0].toUpperCase()+s.slice(1)}))],state.profile.visualTheme||'auto')}${selectField('ambientMotion','Ambient animation',[{id:'on',name:'On · respect reduced motion'},{id:'off',name:'Paused'}],state.profile.ambientMotion||'on')}</div><p class="world-theme-note">Current chapter: ${visual.season}. Your device’s reduced-motion preference always takes priority.</p><button type="button" class="btn primary" data-action="saveVisualPreferences">Save world preferences</button>`;list.prepend(panel);bindActions(panel)}

function stopRoute(){routeCleanup?.();routeCleanup=null;cancelAnimationFrame(routeFrame);routeFrame=0;routeMarker?.remove();routeMarker=null;routePlaying=false;const button=document.querySelector('#route-play');if(button)button.textContent='Preview journey';}
function routeEnhancements(){const shell=document.querySelector('.map-shell');if(!shell)return;const tripId=filters.routeTrip||filters.mapTrip||selectedTrip||state.trips[0]?.id,route=livingModel.savedRoute(state.destinations,tripId);const panel=document.createElement('details');panel.className='route-preview';panel.innerHTML=`<summary>${pixelIcon('compass')} Journey preview · ${route.length} saved ${route.length===1?'stop':'stops'}</summary><div class="row"><select class="field" id="route-trip" aria-label="Route preview trip">${option(state.trips,tripId)}</select><button type="button" class="btn small primary" id="route-play" ${route.length<2?'disabled':''}>Preview journey</button></div><div class="route-stops">${route.map((d,i)=>`<span>${i+1}. ${esc(d.name)}</span>${i<route.length-1?' → ':''}`).join('')}</div><p>Preview connects your saved non-wishlist coordinates in itinerary order. Lines show stop order, not railway directions or booked transport.${route.length<2?' Plan at least two stops with coordinates to play a route.':''}</p><div class="route-preview-status" role="status"></div><small>${state.destinations.filter(d=>d.status==='visited').length} visited stops · ${new Set(state.destinations.filter(d=>d.status==='visited').map(d=>d.country)).size} country stamps</small>`;shell.before(panel);document.querySelector('#route-trip').onchange=e=>{filters.routeTrip=e.target.value;filters.mapTrip=e.target.value;render()};
  document.querySelector('#route-play').onclick=()=>{if(routePlaying){stopRoute();return}if(!map||!window.maplibregl)return toast('The map is still loading. Try again in a moment.');const el=document.createElement('div');el.className='route-vehicle';el.innerHTML=pixelIcon(window.PPMapPreviewTransport||'compass');routeMarker=new maplibregl.Marker({element:el}).setLngLat([Number(route[0].lng),Number(route[0].lat)]).addTo(map);const bounds=new maplibregl.LngLatBounds();route.forEach(d=>bounds.extend([Number(d.lng),Number(d.lat)]));const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches||!livingPreferences().motion;map.fitBounds(bounds,{padding:45,duration:reduced?0:500});const status=panel.querySelector('.route-preview-status');if(reduced){status.textContent=`Route preview: ${route.map(d=>d.name).join(' → ')}`;return}routePlaying=true;document.querySelector('#route-play').textContent='Stop journey';let elapsed=0,last=0,routeVisible=false;
    const duration=Math.max(7000,(route.length-1)*4000),tick=time=>{if(!routePlaying)return;elapsed+=last?Math.min(time-last,60):0;last=time;const position=Math.min(1,elapsed/duration)*(route.length-1),segment=Math.min(route.length-2,Math.floor(position)),progress=position-segment,a=route[segment],b=route[segment+1];routeMarker.setLngLat([Number(a.lng)+(Number(b.lng)-Number(a.lng))*progress,Number(a.lat)+(Number(b.lat)-Number(a.lat))*progress]);status.textContent=`${a.name} → ${b.name}`;if(elapsed>=duration){status.textContent=`Arrived at ${route.at(-1).name} · preview complete`;stopRoute();}else routeFrame=requestAnimationFrame(tick)};
    const sync=()=>{cancelAnimationFrame(routeFrame);last=0;if(routePlaying&&routeVisible&&!document.hidden)routeFrame=requestAnimationFrame(tick)};
    const observer=new IntersectionObserver(entries=>{routeVisible=entries[0].isIntersecting;sync()},{threshold:.05});observer.observe(shell);document.addEventListener('visibilitychange',sync);routeCleanup=()=>{observer.disconnect();document.removeEventListener('visibilitychange',sync)};
  };
}
